    ((int32_t*)st->codec->extradata)[2] = le2me_32(smk->full_size);
    ((int32_t*)st->codec->extradata)[3] = le2me_32(smk->type_size);
    smk->curstream = -1;
    smk->nextpos = url_ftell(pb);
    return 0;
}

